// Parse incoming WhatsApp webhook payload
const body = $input.item.json.body;

if (!body || !body.entry || !body.entry[0]) {
  return [{ json: { skip: true, reason: 'No entry in payload' } }];
}

const entry = body.entry[0];
const changes = entry.changes;

if (!changes || !changes[0]) {
  return [{ json: { skip: true, reason: 'No changes in entry' } }];
}

const value = changes[0].value;

if (!value.messages || !value.messages[0]) {
  return [{ json: { skip: true, reason: 'Not a message event' } }];
}

const message = value.messages[0];

// Bot echo filter: skip if outbound message is echoed back by Meta
const botPhone = value.metadata.display_phone_number.replace(/\D/g, '');
if (message.from === botPhone) {
  return [{ json: { skip: true, reason: 'Bot echo — outbound message reflected back' } }];
}

const contact = value.contacts ? value.contacts[0] : null;

let messageContent = '';
let messageType = message.type;
let interactiveLabel = null;

switch (messageType) {
  case 'text':
    messageContent = message.text.body;
    break;
  case 'interactive':
    if (message.interactive.button_reply) {
      messageContent = message.interactive.button_reply.id;
      interactiveLabel = message.interactive.button_reply.title || null;
    } else if (message.interactive.list_reply) {
      messageContent = message.interactive.list_reply.id;
      interactiveLabel = message.interactive.list_reply.title || null;
    } else if (message.interactive.nfm_reply) {
      messageContent = message.interactive.nfm_reply.response_json;
      interactiveLabel = null;
    }
    break;
  default:
    messageContent = `[${messageType.toUpperCase()}]`;
}

// Guard: skip whitespace-only text messages — blank input would confuse intent classifier
if (messageType === 'text' && (!messageContent || messageContent.trim().length === 0)) {
  return [{ json: { skip: true, reason: 'Whitespace-only text message — skipped' } }];
}

return [{ json: {
  skip: false,
  messageId: message.id,
  timestamp: message.timestamp,
  phoneNumber: message.from,
  phoneNumberFormatted: '+' + message.from,
  contactName: contact ? contact.profile.name : null,
  messageType: messageType,
  messageContent: messageContent,
  messageContentUpper: messageContent.toUpperCase().trim(),
  interactiveLabel: interactiveLabel,
  rawMessage: message,
  metadata: {
    phoneNumberId: value.metadata.phone_number_id,
    displayPhoneNumber: value.metadata.display_phone_number
  }
} }];

// WF-00 → WF-60 canonical shape (inbound from WhatsApp webhook).
// Per-messageType content extraction (TD-F, 2026-05-21):
//   text         → messageContent (text body)
//   interactive  → interactiveLabel (button/list display title) || messageContent (id fallback)
//   other        → messageContent (already bracketed like '[IMAGE]' / '[AUDIO]' / etc.)
const msg = $input.first().json;
const messageType = msg.messageType || 'text';

let content;
if (messageType === 'interactive') {
  content = (msg.interactiveLabel != null && msg.interactiveLabel !== '')
    ? msg.interactiveLabel
    : (msg.messageContent ?? null);
} else {
  content = msg.messageContent ?? null;
}

const metadata = {
  phoneNumber: msg.phoneNumber ?? null,
  contactName: msg.contactName ?? null,
  timestamp: msg.timestamp || new Date().toISOString(),
  rawMessage: msg.rawMessage ?? null
};
if (messageType === 'interactive' && msg.interactiveLabel) {
  metadata.interactiveButtonId = msg.messageContent ?? null;
}

return [{
  json: {
    transport: 'wa',
    direction: 'inbound',
    userId: null,
    consultationId: null,
    messageType,
    content,
    whatsappMessageId: msg.messageId ?? null,
    phoneNumber: msg.phoneNumber ?? msg.phoneNumberFormatted ?? null,
    metadata
  }
}];

